def solve_small(n):
    d = [0] * (n + 1)
    d[1] = 1
    for k in range(2, n + 1):
        d[k] = sum(d[1:k])

    s = 0
    for i in range(1, n):
        s += d[i] / d[i+1]
    return s

for n in range(2, 10):
    print(f"n={n}, s={solve_small(n)}")

def solve_large(n):
    # S = 1 + (n-2)/2
    return 1 + (n-2)/2

for n in range(2, 10):
    print(f"n={n}, formula={solve_large(n)}")
